1	export type Item = {
2	  type: string;
3	  cursed?: boolean;
4	  enchantment?: number;
5	};
6	
7	export type Customer = {
8	  yearsWithMHPCO: number;
9	};
10	
11	export type Damage = {
12	  itemType: string;
13	  amount: number;
14	};
15	
16	export type Incident = {
17	  cause: string;
18	  damages: readonly Damage[];
19	};
20	
21	export type QuoteStep = {
22	  op: "quote";
23	  items: readonly Item[];
24	};
25	
26	export type ClaimStep = {
27	  op: "claim";
28	  // Zero-based index of the quote step that created the policy.
29	  policy: number;
30	  incident: Incident;
31	};
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: readonly Step[];
38	};
39	
40	export type QuoteResult = { premium: number };
41	export type ClaimResult = { payout: number; remainingCap: number };
42	
43	// One entry per scenario step, in order. Each step's `op` selects the shape.
44	export type StepResult = QuoteResult | ClaimResult;
45	
46	export type ScenarioResult = {
47	  results: StepResult[];
48	};
49	
50	const PROCESSING_FEE = 5;
51	
52	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
53	
54	const BASE_PREMIUMS: Record<string, number> = {
55	  sword: 100,
56	  amulet: 60,
57	  staff: 80,
58	  potion: 40,
59	  rune: 25,
60	  moonstone: 25,
61	};
62	
63	// Every percentage modifier is a delta computed against an *unmodified* base
64	// and summed with the others — modifiers never compound. Policy-wide ones use
65	// the policy base, item-specific ones the affected item's own base premium.
66	//
67	// Percentages stay in integer percent points: multiply first, divide by 100
68	// last. A float multiplier such as `base * 1.1` yields 110.00000000000001 for
69	// a sword and breaks the ceil. `(base * 10) / 100` gives exactly 10.
70	const percentOf = (amount: number, percent: number): number =>
71	  (amount * percent) / 100;
72	
73	// The MHPCO insures only the items on its price list. Anything else is a
74	// rejected policy, not a zero-priced one.
75	const lookUpByType = (table: Record<string, number>, type: string): number => {
76	  const value = table[type];
77	
78	  if (value === undefined) {
79	    throw new Error(`unknown item type: ${type}`);
80	  }
81	
82	  return value;
83	};
84	
85	const BLOCK_SIZE = 3;
86	const BLOCK_BASE_PREMIUM = 60;
87	
88	const countByType = (items: readonly Item[]): Map<string, number> => {
89	  const counts = new Map<string, number>();
90	
91	  for (const item of items) {
92	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
93	  }
94	
95	  return counts;
96	};
97	
98	const baseOfGroup = (type: string, count: number): number =>
99	  count === BLOCK_SIZE
100	    ? BLOCK_BASE_PREMIUM
101	    : count * lookUpByType(BASE_PREMIUMS, type);
102	
103	const policyBaseOf = (items: readonly Item[]): number =>
104	  [...countByType(items)].reduce(
105	    (total, [type, count]) => total + baseOfGroup(type, count),
106	    0,
107	  );
108	
109	// A modifier rule: when `applies` holds for the subject, `percent` percent of
110	// the relevant base premium is added. A negative percent is a discount. Every
111	// rule whose predicate holds contributes; the deltas are summed, never
112	// compounded.
113	type ModifierRule<Subject> = {
114	  applies: (subject: Subject) => boolean;
115	  percent: number;
116	};
117	
118	const sumApplicablePercents = <Subject>(
119	  rules: ModifierRule<Subject>[],
120	  subject: Subject,
121	): number =>
122	  rules.reduce(
123	    (total, rule) => (rule.applies(subject) ? total + rule.percent : total),
124	    0,
125	  );
126	
127	// Policy-wide modifiers: each is a percentage of the policy base premium.
128	//
129	// Their subject is the circumstances under which the quote is issued — not the
130	// customer alone, and not the issued policy either (that is `IssuedPolicy`,
131	// which a claim reads). Today those circumstances are just who is asking and
132	// how many quotes they have had; rules that depend on more read the field they
133	// need off the same subject.
134	type QuoteCircumstances = {
135	  customer: Customer;
136	  // Zero-based ordinal among the customer's quotes in this scenario.
137	  quoteOrdinal: number;
138	};
139	
140	const LOYALTY_YEARS_THRESHOLD = 2;
141	const LOYALTY_DISCOUNT_PERCENT = -20;
142	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = -15;
143	
144	const POLICY_MODIFIER_RULES: ModifierRule<QuoteCircumstances>[] = [
145	  { applies: () => true, percent: FIRST_INSURANCE_SURCHARGE_PERCENT },
146	  {
147	    applies: ({ customer }) =>
148	      customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
149	    percent: LOYALTY_DISCOUNT_PERCENT,
150	  },
151	  {
152	    applies: ({ quoteOrdinal }) => quoteOrdinal > 0,
153	    percent: FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT,
154	  },
155	];
156	
157	const policyModifierDelta = (
158	  policyBase: number,
159	  circumstances: QuoteCircumstances,
160	): number =>
161	  percentOf(
162	    policyBase,
163	    sumApplicablePercents(POLICY_MODIFIER_RULES, circumstances),
164	  );
165	
166	// Item-specific modifiers: each is a percentage of the affected item's own
167	// base premium.
168	const CURSE_SURCHARGE_PERCENT = 50;
169	const HIGH_ENCHANTMENT_THRESHOLD = 5;
170	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
171	
172	const ITEM_MODIFIER_RULES: ModifierRule<Item>[] = [
173	  { applies: (item) => item.cursed === true, percent: CURSE_SURCHARGE_PERCENT },
174	  {
175	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
176	    percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
177	  },
178	];
179	
180	const itemModifierDelta = (item: Item): number =>
181	  percentOf(
182	    lookUpByType(BASE_PREMIUMS, item.type),
183	    sumApplicablePercents(ITEM_MODIFIER_RULES, item),
184	  );
185	
186	const quote = (
187	  items: readonly Item[],
188	  circumstances: QuoteCircumstances,
189	): number => {
190	  const policyBase = policyBaseOf(items);
191	  const modifiers =
192	    policyModifierDelta(policyBase, circumstances) +
193	    items.reduce((total, item) => total + itemModifierDelta(item), 0);
194	
195	  // Rounding is in the MHPCO's favour: premiums round up.
196	  return Math.ceil(policyBase + modifiers) + PROCESSING_FEE;
197	};
198	
199	// Insurance values are what an item is insured FOR, distinct from the base
200	// premium charged to insure it.
201	const INSURANCE_VALUES: Record<string, number> = {
202	  sword: 1000,
203	  amulet: 600,
204	  staff: 800,
205	  potion: 400,
206	  rune: 250,
207	  moonstone: 250,
208	};
209	
210	const DEDUCTIBLE_PER_DAMAGE = 100;
211	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
212	
213	const insuranceSumOf = (items: readonly Item[]): number =>
214	  items.reduce(
215	    (sum, item) => sum + lookUpByType(INSURANCE_VALUES, item.type),
216	    0,
217	  );
218	
219	// A policy as a claim sees it: the items it covers, and how much of its cap
220	// is still available. Successive claims against the same policy draw the cap
221	// down, so `remainingCap` is state that outlives the claim step that reads it.
222	type IssuedPolicy = {
223	  items: readonly Item[];
224	  remainingCap: number;
225	};
226	
227	const issuePolicy = (items: readonly Item[]): IssuedPolicy => ({
228	  items,
229	  remainingCap: CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(items),
230	});
231	
232	// A reimbursement clause: when `applies` holds for the damaged item, the
233	// damage is reimbursed at `percent` of its amount.
234	//
235	// Unlike the premium modifiers above, clauses do NOT sum. When several apply
236	// the most restrictive one wins — the lowest percentage. So a clause table
237	// needs no ordering to be correct, and adding a clause can only ever lower a
238	// payout, never raise it.
239	type ReimbursementClause = {
240	  applies: (item: Item) => boolean;
241	  percent: number;
242	};
243	
244	const FULL_REIMBURSEMENT_PERCENT = 100;
245	const HALVED_REIMBURSEMENT_ENCHANTMENT = 8;
246	const HALVED_REIMBURSEMENT_PERCENT = 50;
247	
248	const REIMBURSEMENT_CLAUSES: ReimbursementClause[] = [
249	  {
250	    applies: (item) =>
251	      (item.enchantment ?? 0) >= HALVED_REIMBURSEMENT_ENCHANTMENT,
252	    percent: HALVED_REIMBURSEMENT_PERCENT,
253	  },
254	];
255	
256	// Full reimbursement is the default: with no clause applying, the damage is
257	// covered in full.
258	const reimbursementPercentFor = (item: Item): number =>
259	  REIMBURSEMENT_CLAUSES.reduce(
260	    (percent, clause) =>
261	      clause.applies(item) ? Math.min(percent, clause.percent) : percent,
262	    FULL_REIMBURSEMENT_PERCENT,
263	  );
264	
265	// What a single damage entry is reimbursable for: the reimbursement its
266	// clauses allow, less the deductible. The deductible is charged once per
267	// damaged item, not once per incident, so it belongs here rather than at the
268	// incident level. The policy's cap is NOT applied here — it limits the
269	// incident as a whole, so only `settleClaim` can apply it.
270	//
271	// Takes the whole policy rather than the damage alone because the clauses
272	// grade the reimbursement by the *damaged item's* properties (enchantment,
273	// material), which only the policy can resolve from itemType.
274	// The damaged item is matched by type alone, so with two swords insured both
275	// sword damages resolve to the first. That is harmless while every item of a
276	// type is interchangeable for reimbursement purposes; the case that forces a
277	// positional match is rejecting more damage entries of a type than the policy
278	// covers, which needs a count rather than a lookup.
279	const reimbursableForDamage = (
280	  policy: IssuedPolicy,
281	  damage: Damage,
282	): number => {
283	  const damagedItem = policy.items.find(
284	    (item) => item.type === damage.itemType,
285	  );
286	
287	  const reimbursement = damagedItem
288	    ? percentOf(damage.amount, reimbursementPercentFor(damagedItem))
289	    : damage.amount;
290	
291	  return reimbursement - DEDUCTIBLE_PER_DAMAGE;
292	};
293	
294	// Settles one incident against a policy, returning the payout and the policy
295	// as it stands afterwards. The cap is drawn down here — that is what makes a
296	// second claim against the same policy see less headroom than the first.
297	const settleClaim = (
298	  policy: IssuedPolicy,
299	  incident: Incident,
300	): { payout: number; policy: IssuedPolicy } => {
301	  const reimbursable = incident.damages.reduce(
302	    (total, damage) => total + reimbursableForDamage(policy, damage),
303	    0,
304	  );
305	
306	  // Rounding is in the MHPCO's favour: payouts round down, mirroring the
307	  // premium's round up.
308	  // The policy pays at most what is left of its cap.
309	  const payout = Math.min(Math.floor(reimbursable), policy.remainingCap);
310	
311	  return {
312	    payout,
313	    policy: { ...policy, remainingCap: policy.remainingCap - payout },
314	  };
315	};
316	
317	// What the scenario has established by the time a step runs. Threaded through
318	// the steps in order: each step reads it, and hands the next step the progress
319	// its own execution made.
320	type ScenarioProgress = {
321	  // How many quotes the customer has already been given. Only quote steps
322	  // advance this, so an op that is not a quote leaves it untouched.
323	  quotesSoFar: number;
324	  // Policies created by earlier quote steps, keyed by their step index — the
325	  // handle a later claim step names in its `policy` field.
326	  policies: Map<number, IssuedPolicy>;
327	};
328	
329	// Runs one step against the progress so far, returning its result alongside
330	// the progress the *next* step inherits. Dispatch on `step.op` lives here:
331	// a new op is a new branch, and the loop below is unaffected.
332	const runStep = (
333	  step: Step,
334	  stepIndex: number,
335	  customer: Customer,
336	  progress: ScenarioProgress,
337	): { result: StepResult; progress: ScenarioProgress } => {
338	  if (step.op === "claim") {
339	    const settled = settleClaim(
340	      progress.policies.get(step.policy) ?? issuePolicy([]),
341	      step.incident,
342	    );
343	
344	    return {
345	      result: {
346	        payout: settled.payout,
347	        remainingCap: settled.policy.remainingCap,
348	      },
349	      // The drawn-down policy replaces the one the claim was made against, so
350	      // the next claim against it starts from the reduced cap.
351	      progress: {
352	        ...progress,
353	        policies: new Map(progress.policies).set(step.policy, settled.policy),
354	      },
355	    };
356	  }
357	
358	  return {
359	    result: {
360	      premium: quote(step.items, {
361	        customer,
362	        quoteOrdinal: progress.quotesSoFar,
363	      }),
364	    },
365	    progress: {
366	      quotesSoFar: progress.quotesSoFar + 1,
367	      policies: new Map(progress.policies).set(
368	        stepIndex,
369	        issuePolicy(step.items),
370	      ),
371	    },
372	  };
373	};
374	
375	export const runScenario = (scenario: Scenario): ScenarioResult => {
376	  const results: StepResult[] = [];
377	  let progress: ScenarioProgress = { quotesSoFar: 0, policies: new Map() };
378	
379	  for (const [stepIndex, step] of scenario.steps.entries()) {
380	    const stepRun = runStep(step, stepIndex, scenario.customer, progress);
381	
382	    results.push(stepRun.result);
383	    progress = stepRun.progress;
384	  }
385	
386	  return { results };
387	};
